struct Entry {
    desc: Descriptor,
    info: CString,
    panel: OnceLock<CString>,
}

fn registry() -> &'static [Entry] {
    static REG: OnceLock<Vec<Entry>> = OnceLock::new();
    REG.get_or_init(|| {
        FNS.iter()
            .map(|f| {
                let desc = f();
                let info = CString::new(info_json(&desc)).unwrap_or_default();
                Entry { desc, info, panel: OnceLock::new() }
            })
            .collect()
    })
}

/// An open plugin: the instance plus scratch space for the host's channel pointers.
pub struct Handle {
    inst: Box<dyn Instance>,
    chans: Vec<&'static mut [f32]>,
}

fn guard<T>(fallback: T, f: impl FnOnce() -> T) -> T {
    // never unwind into C++
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)).unwrap_or(fallback)
}

/// Number of plugins in the engine.
#[no_mangle]
pub extern "C" fn pq_count() -> i32 {
    guard(0, || registry().len() as i32)
}

/// JSON describing plugin `i` (name, vendor, class id, categories, parameters). Owned by the engine.
#[no_mangle]
pub extern "C" fn pq_info(i: i32) -> *const c_char {
    guard(std::ptr::null(), || registry().get(i as usize).map(|e| e.info.as_ptr()).unwrap_or(std::ptr::null()))
}

/// JSON describing plugin `i`'s panel (layout, colours, presets). Owned by the engine.
#[no_mangle]
pub extern "C" fn pq_panel(i: i32) -> *const c_char {
    guard(std::ptr::null(), || {
        registry()
            .get(i as usize)
            .map(|e| e.panel.get_or_init(|| CString::new(panel_json(&(e.desc.panel)())).unwrap_or_default()).as_ptr())
            .unwrap_or(std::ptr::null())
    })
}

#[no_mangle]
pub extern "C" fn pq_create(i: i32) -> *mut Handle {
    guard(std::ptr::null_mut(), || match registry().get(i as usize) {
        Some(e) => Box::into_raw(Box::new(Handle { inst: (e.desc.make)(), chans: Vec::with_capacity(8) })),
        None => std::ptr::null_mut(),
    })
}

/// # Safety
/// `h` must come from `pq_create` and not be used afterwards.
#[no_mangle]
pub unsafe extern "C" fn pq_destroy(h: *mut Handle) {
    if !h.is_null() {
        let _ = guard((), || drop(Box::from_raw(h)));
    }
}

/// # Safety
/// `h` must be a live handle.
#[no_mangle]
pub unsafe extern "C" fn pq_set_param(h: *const Handle, i: i32, norm: f32) {
    if let Some(h) = h.as_ref() {
        guard((), || h.inst.set_param(i as usize, norm));
    }
}

/// # Safety
/// `h` must be a live handle.
#[no_mangle]
pub unsafe extern "C" fn pq_get_param(h: *const Handle, i: i32) -> f32 {
    match h.as_ref() {
        Some(h) => guard(0.0, || h.inst.get_param(i as usize)),
        None => 0.0,
    }
}

unsafe fn copy_out(s: &str, buf: *mut c_char, len: i32) -> i32 {
    let bytes = s.as_bytes();
    if !buf.is_null() && len > 0 {
        let n = bytes.len().min(len as usize - 1);
        std::ptr::copy_nonoverlapping(bytes.as_ptr() as *const c_char, buf, n);
        *buf.add(n) = 0;
    }
    bytes.len() as i32
}

/// Text for parameter `i` at `norm` (UTF-8, with unit). Returns the full length.
/// # Safety
/// `h` live; `buf` has room for `len` bytes.
#[no_mangle]
pub unsafe extern "C" fn pq_param_text(h: *const Handle, i: i32, norm: f32, buf: *mut c_char, len: i32) -> i32 {
    match h.as_ref() {
        Some(h) => guard(0, || copy_out(&h.inst.param_text(i as usize, norm), buf, len)),
        None => 0,
    }
}

/// Parse text typed for parameter `i`. Returns 1 and writes `out` on success.
/// # Safety
/// `h` live; `text` a NUL-terminated UTF-8 string; `out` writable.
#[no_mangle]
pub unsafe extern "C" fn pq_param_from_text(h: *const Handle, i: i32, text: *const c_char, out: *mut f32) -> i32 {
    let (Some(h), false, false) = (h.as_ref(), text.is_null(), out.is_null()) else { return 0 };
    let t = CStr::from_ptr(text).to_string_lossy().to_string();
    match guard(None, || h.inst.param_from_text(i as usize, &t)) {
        Some(v) => {
            *out = v;
            1
        }
        None => 0,
    }
}

/// A plain value (as stored in a panel preset) to normalized.
/// # Safety
/// `h` must be a live handle.
#[no_mangle]
pub unsafe extern "C" fn pq_normalize(h: *const Handle, i: i32, plain: f32) -> f32 {
    match h.as_ref() {
        Some(h) => guard(0.0, || h.inst.normalize(i as usize, plain)),
        None => 0.0,
    }
}

/// Returns the latency in samples.
/// # Safety
/// `h` live; not while `pq_process` is running.
#[no_mangle]
pub unsafe extern "C" fn pq_prepare(h: *const Handle, sample_rate: f64, channels: i32, max_block: i32) -> u32 {
    match h.as_ref() {
        Some(h) => guard(0, || h.inst.prepare(sample_rate as f32, channels.max(1) as usize, max_block.max(1) as usize)),
        None => 0,
    }
}

/// # Safety
/// `h` live; not while `pq_process` is running.
#[no_mangle]
pub unsafe extern "C" fn pq_reset(h: *const Handle) {
    if let Some(h) = h.as_ref() {
        guard((), || h.inst.reset());
    }
}

/// Queue a MIDI event `at` samples into the next block. kind: 0 note on (a = note, b = velocity 0..1),
/// 1 note off (a = note), 2 CC (a = controller, b = value 0..1), 3 pitch bend (b = -1..1), 4 all notes off.
/// # Safety
/// `h` live; audio thread.
#[no_mangle]
pub unsafe extern "C" fn pq_midi(h: *const Handle, at: i32, kind: i32, a: i32, b: f32) {
    let Some(h) = h.as_ref() else { return };
    let ev = match kind {
        0 => Midi::On { note: a.clamp(0, 127) as u8, vel: b },
        1 => Midi::Off { note: a.clamp(0, 127) as u8 },
        2 => Midi::Cc { cc: a.clamp(0, 127) as u8, value: b },
        3 => Midi::Bend { value: b },
        _ => Midi::AllOff,
    };
    guard((), || h.inst.midi(at.max(0) as u32, ev));
}

/// Process `n` samples in place. flags: 1 = tempo valid, 2 = beats valid, 4 = playing.
/// # Safety
/// `h` live; `chans` points to `nch` buffers of `n` floats; audio thread.
#[no_mangle]
pub unsafe extern "C" fn pq_process(h: *mut Handle, chans: *const *mut f32, nch: i32, n: i32, tempo: f64, beats: f64, flags: i32) {
    let Some(h) = h.as_mut() else { return };
    if chans.is_null() || nch <= 0 || n <= 0 {
        return;
    }
    h.chans.clear();
    for c in 0..(nch as usize).min(8) {
        let p = *chans.add(c);
        if p.is_null() {
            return;
        }
        h.chans.push(std::slice::from_raw_parts_mut(p, n as usize));
    }
    let tempo = if flags & 1 != 0 { Some(tempo) } else { None };
    let beats = if flags & 2 != 0 { Some(beats) } else { None };
    let playing = flags & 4 != 0;
    let Handle { inst, chans } = h;
    guard((), || inst.process(chans, tempo, beats, playing));
    chans.clear();
}

/// Copy the meters (maximum since the last call) into `out`; returns how many.
/// # Safety
/// `h` live; `out` has room for `max` floats.
#[no_mangle]
pub unsafe extern "C" fn pq_meters(h: *const Handle, out: *mut f32, max: i32) -> i32 {
    let (Some(h), false) = (h.as_ref(), out.is_null()) else { return 0 };
    let o = std::slice::from_raw_parts_mut(out, max.max(0) as usize);
    guard(0, || h.inst.take_meters(o) as i32)
}

/// Save the state (the VST3 versions' JSON format). Returns the full length.
/// # Safety
/// `h` live; `buf` has room for `len` bytes (call with len 0 to ask the size).
#[no_mangle]
pub unsafe extern "C" fn pq_get_state(h: *const Handle, buf: *mut c_char, len: i32) -> i32 {
    match h.as_ref() {
        Some(h) => guard(0, || copy_out(&h.inst.save_state(), buf, len)),
        None => 0,
    }
}

/// Load a state saved by `pq_get_state` or by the VST3 version. Returns 1 on success.
/// # Safety
/// `h` live; `data` points to `len` bytes.
#[no_mangle]
pub unsafe extern "C" fn pq_set_state(h: *const Handle, data: *const u8, len: i32) -> i32 {
    let (Some(h), false) = (h.as_ref(), data.is_null()) else { return 0 };
    let d = std::slice::from_raw_parts(data, len.max(0) as usize);
    guard(0, || h.inst.load_state(d) as i32)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_plugin_runs() {
        let n = pq_count();
        assert!(n > 100);
        for i in 0..n {
            let info = unsafe { CStr::from_ptr(pq_info(i)) }.to_string_lossy().to_string();
            let panel = unsafe { CStr::from_ptr(pq_panel(i)) }.to_string_lossy().to_string();
            assert!(info.starts_with('{') && panel.starts_with('{'), "{info}");
            let h = pq_create(i);
            unsafe {
                pq_prepare(h, 48000.0, 2, 512);
                let mut l = vec![0.0f32; 512];
                let mut r = vec![0.0f32; 512];
                for k in 0..512 {
                    l[k] = (0.2 * (k as f32 * 0.05).sin()) as f32;
                    r[k] = l[k];
                }
                let ptrs = [l.as_mut_ptr(), r.as_mut_ptr()];
                pq_midi(h, 0, 0, 60, 0.8);
                pq_process(h, ptrs.as_ptr(), 2, 512, 120.0, 0.0, 7);
                assert!(l.iter().chain(r.iter()).all(|v| v.is_finite()), "{info}");
                let len = pq_get_state(h, std::ptr::null_mut(), 0);
                let mut buf = vec![0 as c_char; len as usize + 1];
                pq_get_state(h, buf.as_mut_ptr(), len + 1);
                let st = CStr::from_ptr(buf.as_ptr()).to_bytes().to_vec();
                assert_eq!(pq_set_state(h, st.as_ptr(), st.len() as i32), 1, "{info}");
                pq_destroy(h);
            }
        }
    }
}
